                                            statusIntent.putExtra(PARAM_FILENAME,
                                                    outputFile.getAbsolutePath());
                                        } else {
                                            statusIntent.putExtra(PARAM_FILENAME, filename);
                                        }
                                    } else {
                                        statusIntent.putExtra(PARAM_FILENAME, filename);
                                    }
                                } catch (Exception ex) {
                                    // Ignore the exception and continue
                                    Log.w(TAG, "Could not transform JPEG: " + filename, ex);
                                    statusIntent.putExtra(PARAM_FILENAME, filename);
