+    @Override
+    public void onCreate() {
+        super.onCreate();
+        mHandler = new Handler(Looper.getMainLooper());
+
+        mVideoThread = new IntentProcessor("VideoServiceThread");
+        mVideoThread.start();
+
+        mAudioThread = new IntentProcessor("AudioServiceThread");
