	// ����ת��
	private static String hexDigit(byte x) {
		StringBuffer sb = new StringBuffer();
		char c;
		// First nibble
		c = (char) ((x >> 4) & 0xf);
		if (c > 9) {
			c = (char) ((c - 10) + 'a');
		} else {
			c = (char) (c + '0');
		}
		sb.append(c);
		// Second nibble
		c = (char) (x & 0xf);
		if (c > 9) {
			c = (char) ((c - 10) + 'a');
		} else {
			c = (char) (c + '0');
		}
		sb.append(c);
		return sb.toString();
	}

