	// ��path����ӷ�б��
	public static String pathAddBackslash(String path) {
		if (path == null)
			return java.io.File.separator;
		if (path.length() == 0)
			return java.io.File.separator;

		char ch = path.charAt(path.length() - 1);
		if (ch == '/' || ch == '\\')
			return path;
