	/*
	 * ��ѹZIP�ļ� *ʹ�ô˽�ѹ���ļ�ʱ���е��ļ�������Ϊ����
	 */
	public static void unzip(java.util.zip.ZipInputStream in,
			String outputDirectory) throws Exception {
		WizGlobals.ensurePathExists(outputDirectory);
		outputDirectory = WizGlobals.pathAddBackslash(outputDirectory);
		//
		java.util.zip.ZipEntry z;
		while ((z = in.getNextEntry()) != null) {
			System.out.println("unziping " + z.getName());
			if (z.isDirectory()) {
				String name = z.getName();
				WizGlobals.ensurePathExists(outputDirectory + name);
			} else {
				String fileName = outputDirectory + z.getName();
				WizGlobals.ensurePathExists(WizGlobals
						.extractFilePath(fileName));

				java.io.File f = new java.io.File(fileName);
				f.createNewFile();
				java.io.FileOutputStream out = new java.io.FileOutputStream(f);
				//
				byte[] buffer = new byte[1024];
				while (true) {
					int read = in.read(buffer);
					if (read == -1)
						break;
					//
					out.write(buffer, 0, read);
				}
				out.close();
			}
		}
	}

	/**
	 * ʹ�� org.apache.tools.zip.ZipFile ��ѹ�ļ������� java ����е� java.util.zip.ZipFile
	 * ʹ�÷�ʽ��һ�µģ�ֻ�����������ñ��뷽ʽ�� �ӿڡ�
	 * 
	 * ע��apache û���ṩ ZipInputStream �࣬����ֻ��ʹ�����ṩ��ZipFile ����ȡѹ���ļ���
	 * 
	 * @param archive
	 *            ѹ����·��
	 * @param decompressDir
	 *            ��ѹ·��
	 * @throws IOException
	 * @throws FileNotFoundException
	 * @throws ZipException
	 */

	// archive=һ���ļ���·��+�ļ���
	// public static void unZipByApache(String archive, String decompressDir)
	@SuppressWarnings("rawtypes")
	public static void unZipByApache(File archive, String decompressDir,
			WizAttachment wizAtt) throws IOException, FileNotFoundException,
			ZipException {
		BufferedInputStream bi;
		ZipFile zf = new ZipFile(archive, "GBK");// ֧������

		Enumeration e = zf.getEntries();
		while (e.hasMoreElements()) {
			ZipEntry ze2 = (ZipEntry) e.nextElement();
			String entryName = null;
			if (wizAtt == null) {
				entryName = ze2.getName();
			} else {
				entryName = wizAtt.name;
			}
			String path = decompressDir + "/" + entryName;
			if (ze2.isDirectory()) {
				File decompressDirFile = new File(path);
				if (!decompressDirFile.exists()) {
					decompressDirFile.mkdirs();
				}
			} else {
				String fileDir = path.substring(0, path.lastIndexOf("/"));
				File fileDirFile = new File(fileDir);
				if (!fileDirFile.exists()) {
					fileDirFile.mkdirs();
				}
				BufferedOutputStream bos = new BufferedOutputStream(
						new FileOutputStream(decompressDir + "/" + entryName));
				bi = new BufferedInputStream(zf.getInputStream(ze2));
				byte[] readContent = new byte[1024];
				int readCount = bi.read(readContent);
				while (readCount != -1) {
					bos.write(readContent, 0, readCount);
					readCount = bi.read(readContent);
				}
				bos.close();
			}
		}
		zf.close();
	}

	/*
	 * ʹ��Apache����ѹ�� srcFileָ��δѹ�����ļ� zipFileָ����ѹ�����ļ�
	 */
	public static void ZipByApache(File srcFile, File zipFile) {
		ZipOutputStream out = null;
		boolean boo = false;// �Ƿ�ѹ���ɹ�
		try {
			CheckedOutputStream cos = new CheckedOutputStream(
					new FileOutputStream(zipFile), new CRC32());
			out = new ZipOutputStream(cos);
			File[] files = srcFile.listFiles();
			if (files != null && files.length > 0) {
				for (int i = 0; i < files.length; i++) {
					Zip(files[i], out, "", true);
				}
			}
			boo = true;
		} catch (IOException ex) {
			throw new RuntimeException(ex);
		} finally {
			try {
				if (out != null)
					out.close();
			} catch (IOException ex) {
				throw new RuntimeException("�ر�Zip����������쳣", ex);
			} finally {
				// �������
				if (!boo && zipFile.exists())// ѹ�����ɹ�,
					zipFile.delete();
			}
		}
	}

	/**
	 * ѹ��zip�ļ�
	 * 
	 * @param file
	 *            ѹ�����ļ�����
	 * @param out
	 *            ���ZIP��
	 * @param dir
	 *            ��Ը�Ŀ¼����
	 * @param boo
	 *            �Ƿ�ѿ�Ŀ¼ѹ����ȥ
	 */
	public static void Zip(File file, ZipOutputStream out, String dir,
			boolean boo) throws IOException {
		if (file.isDirectory()) {// ��Ŀ¼
			File[] listFile = file.listFiles();// �ó�Ŀ¼�����е��ļ�����
			if (listFile.length == 0 && boo) {// ��Ŀ¼ѹ��
				out.putNextEntry(new ZipEntry(dir + file.getName() + "/"));// ��ʵ��������ZIP����
				// System.out.println("ѹ��." + dir + file.getName() + "/");
				return;
			} else {
				for (File cfile : listFile) {
					Zip(cfile, out, dir + file.getName() + "/", boo);// �ݹ�ѹ��
				}
			}
		} else if (file.isFile()) {// ���ļ�
			// System.out.println("ѹ��." + dir + file.getName() + "/");
			byte[] bt = new byte[2048 * 2];
			ZipEntry ze = new ZipEntry(dir + file.getName());// ����ѹ��ʵ��
			ze.setSize(file.length());
			// ����ѹ��ǰ���ļ���С
			out.putNextEntry(ze);// ��ʵ��������ZIP����
			FileInputStream fis = null;
			try {
				fis = new FileInputStream(file);
				int i = 0;
				while ((i = fis.read(bt)) != -1) {// ѭ��������д�����Zip����
					out.write(bt, 0, i);
				}
			} catch (IOException ex) {
				// throw new IOException("д��ѹ���ļ������쳣",ex);
				throw new IOException("д��ѹ���ļ������쳣");
			} finally {
				try {
					if (fis != null)
						fis.close();// �ر�������
				} catch (IOException ex) {
					throw new IOException("�ر������������쳣");
				}
			}
		}
	}

