		try {
			in = new FileInputStream(zipFile);
			byte[] part_data = new byte[4];
			in.read(part_data);
			if (part_data != null) {// 90 73 87 82
				if (part_data[0] == 90 && part_data[1] == 73
						&& part_data[2] == 87 && part_data[3] == 82) {
					return true;
				}
			}
		} catch (Exception e) {
		} finally {
			try {
				in.close();
			} catch (IOException e) {
			}
		}
		return false;
	}

