+        if (newMask != null) {
+            if (mFinalMask != null && !mFinalMask.isRecycled()) {
+                mFinalMask.recycle();
+            }
+            mFinalMask = newMask;
+        }
+    }
+
+    //Utils
+    private PorterDuffXfermode getModeFromInteger(int index) {
+        PorterDuff.Mode mode = null;
+        switch (index) {
+            case MODE_ADD:
+                if (Build.VERSION.SDK_INT >= 11) {
+                    mode = PorterDuff.Mode.ADD;
+                } else {
+                    log("MODE_ADD is not supported on api lvl " + Build.VERSION.SDK_INT);
+                }
+            case MODE_CLEAR:
+                mode = PorterDuff.Mode.CLEAR;
+                break;
+            case MODE_DARKEN:
+                mode = PorterDuff.Mode.DARKEN;
+                break;
+            case MODE_DST:
+                mode = PorterDuff.Mode.DST;
+                break;
+            case MODE_DST_ATOP:
+                mode = PorterDuff.Mode.DST_ATOP;
+                break;
+            case MODE_DST_IN:
+                mode = PorterDuff.Mode.DST_IN;
+                break;
+            case MODE_DST_OUT:
+                mode = PorterDuff.Mode.DST_OUT;
+                break;
+            case MODE_DST_OVER:
+                mode = PorterDuff.Mode.DST_OVER;
+                break;
+            case MODE_LIGHTEN:
+                mode = PorterDuff.Mode.LIGHTEN;
+                break;
+            case MODE_MULTIPLY:
+                mode = PorterDuff.Mode.MULTIPLY;
+                break;
+            case MODE_OVERLAY:
+                if (Build.VERSION.SDK_INT >= 11) {
+                    mode = PorterDuff.Mode.OVERLAY;
+                } else {
+                    log("MODE_OVERLAY is not supported on api lvl " + Build.VERSION.SDK_INT);
+                }
+            case MODE_SCREEN:
+                mode = PorterDuff.Mode.SCREEN;
+                break;
+            case MODE_SRC:
+                mode = PorterDuff.Mode.SRC;
+                break;
+            case MODE_SRC_ATOP:
+                mode = PorterDuff.Mode.SRC_ATOP;
+                break;
+            case MODE_SRC_IN:
