+            arrowPath.close();
+        }
+        canvas.drawPath(arrowPath, paintArrow);
+
+        //draw bottom tick
+        canvas.drawLine(centerX, h - (TICK_OFFSET + TICK_LENGTH) * displayDensity, centerX, h - (TICK_OFFSET - TICK_LENGTH) * displayDensity, paintTick);
