package com.quackware.gifdroid;

import java.util.ArrayList;
import com.googlecode.javacv.cpp.opencv_core.IplImage;
import com.quackware.gifdroid.util.GIFPrep;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.Bitmap.Config;
import android.media.MediaMetadataRetriever;
import android.util.Log;


public class GIFCreator {

	Context _context;

	double _duration;
	long _counter = 1;

	long _incrementer;
	String _path;

	ArrayList<Bitmap> bitmapList;
	ModifiedFrameGrabber f;
	private GIFPrep _gifInfo;

	private static final String TAG = "GIFCreator";

	public GIFCreator(Context context, String path, double fps) {
		_context = context;
		bitmapList = new ArrayList<Bitmap>();
		_path = path;
	}

	private Bitmap iplToBitmap(IplImage image)
	{
		Log.i(TAG,"height: " + image.height() + " width: " + image.width());
		Bitmap b = Bitmap.createBitmap(image.width(),image.height(),Config.ARGB_8888);
		b.copyPixelsFromBuffer(image.getByteBuffer());
		Bitmap newB = null;
		try
		{
			Log.i(TAG,"Scale: " + _gifInfo.getWidth() + " x " + _gifInfo.getHeight());
			newB = Bitmap.createScaledBitmap(b, _gifInfo.getWidth(), _gifInfo.getHeight(), true);
		}
		catch(Exception ex)
		{
			Log.i("test","caught exception " + ex.getMessage());
		}
		b.recycle();
		return newB;
	}

	private Bitmap scale(Bitmap largeBitmap)
	{
		return Bitmap.createScaledBitmap(largeBitmap, _gifInfo.getWidth(), _gifInfo.getHeight(), true);
	}

	public GIFFrames createGIFFramesMMDR(GIFPrep gifInfo)
	{
		try
		{
			_gifInfo = gifInfo;
			MediaMetadataRetriever mmr = new MediaMetadataRetriever();
			mmr.setDataSource(_path);
			GIFFrames gifFrames = new GIFFrames(gifInfo.getFps()*1000);
			double inc = 1000*1000 / gifInfo.getFps();
			for(double i = Math.floor(gifInfo.getStartTime());i<Math.ceil(gifInfo.getEndTime());i+= inc)
			{
				gifFrames.addBitmap(scale(mmr.getFrameAtTime((long)i,MediaMetadataRetriever.OPTION_CLOSEST)));
			}

			return gifFrames;
		}
		catch(Exception ex)
		{
			ex.printStackTrace();
			return null;
		}
	}

	public GIFFrames createGIFFrames(GIFPrep gifInfo)
	{
		try
		{
			_gifInfo = gifInfo;
			f = new ModifiedFrameGrabber(_path);
			f.start();
			//microseconds
			//1000000 = 1sec

			GIFFrames gifFrames = new GIFFrames(gifInfo.getFps()*1000);
			//Seek to the first frame.
			//todo, add seek function to fix bug
			gifFrames.addBitmap(iplToBitmap(f.grabAtTimestamp((long) gifInfo.getStartTime())));
			for(int i = 0;i<gifInfo.getFps();i++)
			{
				f.grab();
			}

			double fpsRecord = 30;
			double fpsDivider = fpsRecord / gifInfo.getFps();
			double deltaTime = gifInfo.getEndTime() - gifInfo.getStartTime();
			for(int timeInc = 1000000;timeInc < deltaTime;timeInc+= 1000000)
			{
				for(int fpsRecordInc = 0;fpsRecordInc < gifInfo.getFps();fpsRecordInc++)
				{
					try
					{
						gifFrames.addBitmap(iplToBitmap(f.grab()));
					}
					catch(Exception ex)
					{
						ex.printStackTrace();
						f.stop();
						return gifFrames;
					}
					for(int i = 0;i<fpsDivider;i++)
					{
						f.grab();
					}

				}
			}
			f.stop();
			return gifFrames;
		}

		catch(Exception ex)
		{
			ex.printStackTrace();
			return null;
		}
	}

	public ArrayList<Bitmap> getBitmapList()
	{
		return bitmapList;
	}


	public GIF createGIF(ArrayList<Bitmap> selectedBitmaps) {
		GIF g = new GIF(selectedBitmaps,_gifInfo.getFps(),_gifInfo.getDelay());
		g.create(_context,_gifInfo.getHeight(),_gifInfo.getWidth());
		return g;
	}

}

package com.choiboi.imagecroppingexample;

import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Color;

public class ImageProcess {

    /*
     * This method gets the image inside the template area and returns that bitmap.
     * Process of how this method works:
     *     1) Combine img and templateImage together with templateImage being on the top.
     *     2) Create a new blank bitmap using the given width and height, which is the 
     *        size of the template on the screen.
     *     3) Starting in the center go through the image quadrant by quadrant copying 
     *        the pixel value onto the new blank bitmap.
     *     4) Once it hits the pixel colour values of the template lines, then set the pixel
     *        values from that point on transparent.
     *     5) Return the cropped bitmap.
     */
    public static Bitmap cropImage(Bitmap img, Bitmap templateImage, int width, int height) {
        // Merge two images together.
        Bitmap bm = Bitmap.createBitmap(img.getWidth(), img.getHeight(), Bitmap.Config.ARGB_8888);
        Canvas combineImg = new Canvas(bm);
        combineImg.drawBitmap(img, 0f, 0f, null);
        combineImg.drawBitmap(templateImage, 0f, 0f, null);

        // Create new blank ARGB bitmap.
        Bitmap finalBm = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888);

        // Get the coordinates for the middle of combineImg.
        int hMid = bm.getHeight() / 2;
        int wMid = bm.getWidth() / 2;
        int hfMid = finalBm.getHeight() / 2;
        int wfMid = finalBm.getWidth() / 2;

        int y2 = hfMid;
        int x2 = wfMid;

        for (int y = hMid; y >= 0; y--) {
            boolean template = false;
            // Check Upper-left section of combineImg.
            for (int x = wMid; x >= 0; x--) {
                if (x2 < 0) {
                    break;
                }

                int px = bm.getPixel(x, y);
                if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                    template = true;
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else if (template) {
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else {
                    finalBm.setPixel(x2, y2, px);
                }
                x2--;
            }
            // Check upper-right section of combineImage.
            x2 = wfMid;
            template = false;
            for (int x = wMid; x < bm.getWidth(); x++) {
                if (x2 >= finalBm.getWidth()) {
                    break;
                }

                int px = bm.getPixel(x, y);
                if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                    template = true;
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else if (template) {
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else {
                    finalBm.setPixel(x2, y2, px);
                }
                x2++;
            }

            // Once we reach the top-most part on the template line, set pixel value transparent
            // from that point on.
            int px = bm.getPixel(wMid, y);
            if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                for (int y3 = y2; y3 >= 0; y3--) {
                    for (int x3 = 0; x3 < finalBm.getWidth(); x3++) {
                        finalBm.setPixel(x3, y3, Color.TRANSPARENT);
                    }
                }
                break;
            }

            x2 = wfMid;
            y2--;
        }

        x2 = wfMid;
        y2 = hfMid;
        for (int y = hMid; y <= bm.getHeight(); y++) {
            boolean template = false;
            // Check bottom-left section of combineImage.
            for (int x = wMid; x >= 0; x--) {
                if (x2 < 0) {
                    break;
                }

                int px = bm.getPixel(x, y);
                if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                    template = true;
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else if (template) {
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else {
                    finalBm.setPixel(x2, y2, px);
                }
                x2--;
            }

            // Check bottom-right section of combineImage.
            x2 = wfMid;
            template = false;
            for (int x = wMid; x < bm.getWidth(); x++) {
                if (x2 >= finalBm.getWidth()) {
                    break;
                }

                int px = bm.getPixel(x, y);
                if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                    template = true;
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else if (template) {
                    finalBm.setPixel(x2, y2, Color.TRANSPARENT);
                } else {
                    finalBm.setPixel(x2, y2, px);
                }
                x2++;
            }

            // Once we reach the bottom-most part on the template line, set pixel value transparent
            // from that point on.
            int px = bm.getPixel(wMid, y);
            if (Color.red(px) == 234 && Color.green(px) == 157 && Color.blue(px) == 33) {
                for (int y3 = y2; y3 < finalBm.getHeight(); y3++) {
                    for (int x3 = 0; x3 < finalBm.getWidth(); x3++) {
                        finalBm.setPixel(x3, y3, Color.TRANSPARENT);
                    }
                }
                break;
            }

            x2 = wfMid;
            y2++;
        }

        // Get rid of images that we finished with to save memory.
        img.recycle();
        templateImage.recycle();
        bm.recycle();
        return finalBm;
    }

