+	private boolean unlocksVerticalLock(MotionEvent e) {
+		float dx;
+		float dy;
+		
+		dx = Math.abs(e.getX()-downX);
+		dy = Math.abs(e.getY()-downY);
+		
+		if (dy > 0.25 * dx || maxExcursionY > 0.8 * dx)
+			return false;
+		
+		return dx > width/5 || dx > height/5;
+	}
