+
+	/**
+	 * 
+	 * @param event
+	 * @return distance in multitouch event
+	 */
+	private float distance(MotionEvent event) {
+		double dx = event.getX(0)-event.getX(1);
+		double dy = event.getY(0)-event.getY(1);
+		return (float)Math.sqrt(dx*dx+dy*dy);
+	}
