+	/**
+	 * Handle touch event coming from Android system.
+	 */
+	public boolean onTouch(View v, MotionEvent event) {
+		downX = event.getX();
+		downY = event.getY();
+
+		if (downX <= this.width * 0.15){
+			if (event.getAction() == MotionEvent.ACTION_DOWN)
+				doAction(actions.getAction(Actions.LEFT_TAP));
+			return true;
+		}
+
+		if (downX >= this.width * 0.85) {
+			if (event.getAction() == MotionEvent.ACTION_DOWN)
+				doAction(actions.getAction(Actions.RIGHT_TAP));
+			return true;
+		}
+
+		this.lastControlsUseMillis = System.currentTimeMillis();
+		Log.v(TAG, ""+event.getAction());
+		if (!gestureDetector.onTouchEvent(event)) {
+			// Log.v(TAG, ""+event.getAction());
+			if (event.getAction() == MotionEvent.ACTION_DOWN) {
+                if (this.eo_crop) {
+                    Log.v(TAG, "crop differ in touch!");
+                    this.xoffset = this.xoffset_eo[this.currentPage & 1];
+                    this.yoffset = this.yoffset_eo[this.currentPage & 1];
+                } 
+				last_viewx0 = this.left - this.width/2 + this.xoffset;
+				last_viewy0 = this.top - this.height/2 + this.yoffset;
+
+				downX = event.getX();
+				downY = event.getY();
+
+				lastX = downX;
+				lastY = downY;
+				lockedVertically = verticalScrollLock;
+				maxExcursionY = 0;
+				scroller = null;
+			}
+	        else if (event.getAction() == MotionEvent.ACTION_POINTER_2_DOWN
+	        		&& event.getPointerCount() >= 2) {
+	        	float d = distance(event);
+	        	if (d > 20f) {
+		        	this.mtZoomActive = true;
+		        	this.mtZoomValue = 1f;
+		        	this.mtDistanceStart = distance(event);
+		        	this.mtLastDistance = this.mtDistanceStart;
+	        	}
+	        }
+			else if (event.getAction() == MotionEvent.ACTION_MOVE){
+				if (this.mtZoomActive && event.getPointerCount() >= 2) {
+					float d = distance(event);
+					if (d > 20f) {
+						d = .6f * this.mtLastDistance + .4f * d;
+						this.mtLastDistance = d;
+						this.mtZoomValue = d / this.mtDistanceStart;
+						if (this.mtZoomValue < 0.1f)
+							this.mtZoomValue = 0.1f;
+						else if (mtZoomValue > 10f)
+							this.mtZoomValue = 10f;
+						Log.v(TAG, "MT zoom "+this.mtZoomValue);
+						invalidate();
+					}
+				}
+				else {
+					if (lockedVertically && unlocksVerticalLock(event)) 
+						lockedVertically = false;
+					
+					float dx = event.getX() - lastX;
+					float dy = event.getY() - lastY;
+					
+					float excursionY = Math.abs(event.getY() - downY);
+	
+					if (excursionY > maxExcursionY)
+						maxExcursionY = excursionY;
+					
+					if (lockedVertically)
+						dx = 0;
+					
+					doScroll((int)-dx, (int)-dy);
+					
+					lastX = event.getX();
+					lastY = event.getY();
+				}
+			}
+			else if (event.getAction() == MotionEvent.ACTION_UP ||
+					event.getAction() == MotionEvent.ACTION_POINTER_2_UP) {
+				cur_viewx0 = this.left - this.width/2 + this.xoffset;
+				cur_viewy0 = this.top - this.height/2 + this.yoffset;
+				updateXYOffsets(this.xoffset + cur_viewx0 - last_viewx0,
+								this.yoffset + cur_viewy0 - last_viewy0);
+                if (eo_crop) {
+                    Log.v(TAG, "crop differ in touch!");
+                    updateXYEOOffsets(this.xoffset,
+                                      this.yoffset,
+                                      this.currentPage & 1);
+                }
+				Log.v(TAG, "=====================Last Y0: " + last_viewy0);
+				Log.v(TAG, "=====================Now  Y0: " + cur_viewy0);
+
+
+				Log.v(TAG, "=====================Last X0: " + last_viewx0);
+				Log.v(TAG, "=====================Now  X0: " + cur_viewx0);
+
+				if (this.mtZoomActive) {
+					this.mtDebounce = SystemClock.uptimeMillis();
+					this.mtZoomActive = false;
+					zoom(this.mtZoomValue);
+				}
+
+			}						
+		}
+		return true;
+	}
