+	public float pagePosition(int page) {
+		float top = 0;
+		
+		for(int i = 0; i < page; ++i) {
+			top += this.getCurrentPageHeight(i);
+		}
+		
+		if (page > 0)
+			top += scale((float)marginY) * (float)(page);
