+    private static Map<String, Bitmap> getBCache(){
+        if(bigCache == null){
+            bigCache = Collections.synchronizedMap(new BitmapCache(BIG_MAX, BIG_PIXELS, BIG_TPIXELS));
+        }
+        return bigCache;
