    public void setEOCrop(boolean c, boolean resume) {
        DocumentOptions op;
        String str;

        if (resume) {
            op = new DocumentOptions(this.activity.getApplicationContext());
            str = op.getValue(this.filePath, "EOCROP");
            this.eo_crop = Boolean.parseBoolean(str);
            Log.v(TAG, "RESUME: >>>>> : " + this.eo_crop);
            ((OpenFileActivity)activity).updateEOCropItem(this.eo_crop);
        } else {
            this.eo_crop = c;
            op = new DocumentOptions(this.activity.getApplicationContext());
            op.setValue(this.filePath, "EOCROP", Boolean.toString(this.eo_crop));
        }
    }

