+            // shrink can trigger a synchronous onLayout call, so we
+            // post this to avoid a stack overflow / tangled onLayout calls
+            post(new Runnable() {
+                public void run() {
+                    changeState(mStateAfterFirstLayout, false);
+                }
+            });
+        }
+    }
