+			mRangePaints[i] = new Paint(Paint.LINEAR_TEXT_FLAG | Paint.ANTI_ALIAS_FLAG);
+			mRangePaints[i].setColor(mRangeColors[i]);
+			mRangePaints[i].setStyle(Paint.Style.FILL);
+			mRangePaints[i].setStrokeWidth(0.005f);
