+			mRangePaints[i].setTypeface(Typeface.SANS_SERIF);
+			mRangePaints[i].setTextAlign(Align.CENTER);
+			mRangePaints[i].setShadowLayer(0.005f, 0.002f, 0.002f, mTextShadowColor);
+		}
