+            // supposed to be
+            final View motionView = supportsOverscroll &&
+                    getChildCount() > 0 ? getChildAt(0) : null;
+            final int motionViewPrevTop = motionView != null ? motionView.getTop() : 0;
+            final boolean stopped = !trackMotionScroll(dy, false);
