+        final int colCount = mColCount;
+        if (mItemTops == null || mItemBottoms == null || mItemTops.length != colCount ||
+                mItemBottoms.length != colCount) {
+            mItemTops = new int[colCount];
+            mItemBottoms = new int[colCount];
