+            view.setLayoutParams(lp);
+        }
+
+        final LayoutParams sglp = (LayoutParams) view.getLayoutParams();
+        sglp.position = position;
+        sglp.viewType = positionViewType;
+        sglp.id = id;
+        sglp.span = itemColumnSpan;
