+            if(getWidth() > 0 && switchScroller != null){   //如果已经绘制完成
+                switchScroller.startScroll(checked);
+            }else{
+                setSlideX(isChecked() ? tempMinSlideX : tempMaxSlideX);  //直接修改X轴坐标，因为尚未绘制完成的时候，动画执行效果不理想，所以直接修改坐标，而不执行动画
