+        int padding = super.getCompoundPaddingRight() + (frameDrawable!=null?frameDrawable.getIntrinsicWidth():0);
+        if (!TextUtils.isEmpty(getText())) {
+            padding += withTextInterval;
+        }
+        return padding;
