+    private int setSlideX(int newSlideX) {
+        //防止滑动超出范围
+        if(newSlideX < tempMinSlideX) newSlideX = tempMinSlideX;
+        if(newSlideX > tempMaxSlideX) newSlideX = tempMaxSlideX;
+        //计算本次距离增量
+        int addDistance = newSlideX - tempSlideX;
+        this.tempSlideX = newSlideX;
+        return addDistance;
+    }
