+	/*
+	 * 计算图片在内存中，占的大小
+	 * 2 是像素的深度，一般占用两个字节
+	 */
+	public static long calculateBitmapSize(BitmapFactory.Options options) {
+		int depth = 2;
+		int sampleSize = 1;
+		if (options.inPreferredConfig == null) {
+			depth = 2;
+		} else {
+		    switch (options.inPreferredConfig) {
+		    case ARGB_4444: depth = 2; break;
+		    case ARGB_8888: depth = 4; break;
+		    default: depth = 2; break;
+		    }
+		}
+
+		if (options.inSampleSize > 1) {
+			sampleSize = options.inSampleSize;
+		}
+
+		if (Constants.DEBUG) {
+			Log.d(TAG, "image widht:" + options.outWidth + ", hight:" + options.outHeight + ", inSampleSize:" + sampleSize);
+		}
+
+		return options.outWidth * options.outHeight * depth; //options.outWidth * options.outHeight * depth / sampleSize
+	}
