+        int srcWidth = bitmap.getWidth();
+        int srcHeight = bitmap.getHeight();
+        int width = maxSize;
+        int height = maxSize;
+        boolean needsResize = false;
+        if (srcWidth > srcHeight) {
+            if (srcWidth > maxSize) {
+                needsResize = true;
+                height = ((maxSize * srcHeight) / srcWidth);
+            }
+        } else {
+            if (srcHeight > maxSize) {
+                needsResize = true;
+                width = ((maxSize * srcWidth) / srcHeight);
+            }
+        }
