+        private String debugVersions() {
+            StringBuffer sb = new StringBuffer();
+            sb.append("bot=");
+            sb.append(bottom);
+            sb.append(" top=");
+            sb.append(top);
+            sb.append(" [");
+            for (int i=0; i<versions.size(); i++) {
+                if (i > 0) sb.append(" ");
+                sb.append(versions.get(i).version);
+            }
+            sb.append("]");
+            return sb.toString();
+        }
+        public Tile(int x, int y, int version) {
+            this.x = x;
+            this.y = y;
