+    public void commitStroke() {
+        if (mTiledCanvas == null) {
+            final Throwable e = new Throwable();
+            e.fillInStackTrace();
+            Log.v(TAG, "commitStroke before mTiledCanvas inited", e);
+            return;
+        }
+        mTiledCanvas.commit();
+    }
+
+    public void undo() {
+        if (mTiledCanvas == null) {
+            Log.v(TAG, "undo before mTiledCanvas inited");
+        }
+        mTiledCanvas.step(-1);
+
+        invalidate();
+    }
