+    /**
+     * Release the semaphore which arbitrates access to the editor
+     */
+    private void unlock() {
+        if (Log.isLoggable(TAG, Log.DEBUG)) {
+            Log.d(TAG, "unlock: releasing semaphore");
+        }
+        mLock.release();
+    }
