                    generatePreview(videoEditor, true);
                    completeRequest(intent);
                    break;
                }

                case OP_OVERLAY_REMOVE: {
                    logd("OP_OVERLAY_REMOVE: " + intent.getStringExtra(PARAM_STORYBOARD_ITEM_ID));

