	private void initCameraLayout() {
		new AsyncTask<String, Integer, Boolean>(){

			@Override
			protected Boolean doInBackground(String... params) {
				boolean result = setCamera();

				if(!initSuccess){

					initVideoRecorder();
					startRecording();

					initSuccess = true;
				}

				return result;
			}

			@Override
