    // This method just applies the value mChildrenLayersEnabled to all the pages that
    // will be rendered on the next frame.
    // We do this because calling setChildrenLayersEnabled on a view that's not
    // visible/rendered causes slowdowns on some graphics cards
    private void syncChildrenLayersEnabledOnVisiblePages() {
        if (mChildrenLayersEnabled) {
            getVisiblePages(mTempVisiblePagesRange);
            final int leftScreen = mTempVisiblePagesRange[0];
            final int rightScreen = mTempVisiblePagesRange[1];
            if (leftScreen != -1 && rightScreen != -1) {
                for (int i = leftScreen; i <= rightScreen; i++) {
                    ViewGroup page = (ViewGroup) getPageAt(i);
                    final float ALPHA_THRESHOLD = 0.5f / 24;
                    if (page.getVisibility() == VISIBLE &&
                            page.getAlpha() > ALPHA_THRESHOLD) {
//                        ((ViewGroup)getPageAt(i)).setChildrenLayersEnabled(true);
                        setChildrenLayersEnabled((ViewGroup)getPageAt(i), true);
                    }
                }
            }
        }
    }

    private void setChildrenLayersEnabled(ViewGroup vg, boolean on)
    {
    	try
    	{
    		Method m = ViewGroup.class.getDeclaredMethod("setChildrenLayersEnabled", boolean.class);
    		m.invoke(vg, on);
    	}
    	catch (Exception e)
    	{
    		e.printStackTrace();
    	}
    }

    @Override
    protected void dispatchDraw(Canvas canvas) {
        super.dispatchDraw(canvas);

        if (mInScrollArea && !LauncherApplication.isScreenLarge()) {
            final int width = getWidth();
            final int height = getHeight();
            final int pageHeight = getChildAt(0).getHeight();

            // Set the height of the outline to be the height of the page
            final int offset = (height - pageHeight - getPaddingTop() - getPaddingBottom()) / 2;
            final int paddingTop = getPaddingTop() + offset;
            final int paddingBottom = getPaddingBottom() + offset;

            final CellLayout leftPage = (CellLayout) getChildAt(mCurrentPage - 1);
            final CellLayout rightPage = (CellLayout) getChildAt(mCurrentPage + 1);

            if (leftPage != null && leftPage.getIsDragOverlapping()) {
                final Drawable d = getResources().getDrawable(R.drawable.page_hover_left_holo);
                d.setBounds(computeHorizontalScrollOffset(), paddingTop, computeHorizontalScrollOffset() + d.getIntrinsicWidth(),
                        height - paddingBottom);
                d.draw(canvas);
            } else if (rightPage != null && rightPage.getIsDragOverlapping()) {
                final Drawable d = getResources().getDrawable(R.drawable.page_hover_right_holo);
                d.setBounds(computeHorizontalScrollOffset() + width - d.getIntrinsicWidth(), paddingTop, computeHorizontalScrollOffset() + width,
                        height - paddingBottom);
                d.draw(canvas);
            }
        }
    }

