	//判断是否需要录制，手指按下继续，抬起时暂停
	boolean recording = false;
	//判断是否开始了录制，第一次按下屏幕时设置为true
	boolean	isRecordingStarted = false;
	//是否开启闪光灯
	boolean isFlashOn = false;
