	//每次按下手指和抬起之间的暂停时间
	long totalPauseTime = 0;
	//手指抬起是的时间
	long pausedTime = 0;
	//总的暂停时间
	long stopPauseTime = 0;
	//录制的有效总时间
	long totalTime = 0;
	//视频帧率
	private int frameRate = 30;
	//录制的最长时间
	private int recordingTime = 6000;
	//录制的最短时间
	private int recordingMinimumTime = 6000;
	//提示换个场景
	private int recordingChangeTime = 3000;

