+            matrix.postTranslate(getWidth() / 2, getHeight() / 2);
+        }
+        return matrix;
+    }
+
+    public boolean isOrientationChanged() {
+        return (mRotation / 90) % 2 != 0;
+    }
+
+    public int getHeight() {
+        if (isOrientationChanged()) {
+            return mBitmap.getWidth();
+        } else {
+            return mBitmap.getHeight();
+        }
+    }
+
+    public int getWidth() {
+        if (isOrientationChanged()) {
+            return mBitmap.getHeight();
+        } else {
+            return mBitmap.getWidth();
+        }
+    }
+
+    public void recycle() {
+        if (mBitmap != null) {
+            mBitmap.recycle();
+            mBitmap = null;
+        }
+    }
+}

