+
+        // Tell the javascript to handle this if not in selection mode
+        // if(!this.isInSelectionMode()){
+//        this.loadUrl("javascript:android.selection.longTouch();");
+        mScrolling = true;
+        // }
+
+        // Don't let the webview handle it
+        return true;
