        if (!isenlarge) {
            if (isScale) {
                scaleWidth = scaleWidth < scaleHeight ? scaleWidth
                        : scaleHeight;
                scaleHeight = scaleWidth;
            }
        } else {
            if (isScale) {
                scaleWidth = scaleWidth > scaleHeight ? scaleWidth
                        : scaleHeight;
                scaleHeight = scaleWidth;
            }
