+            task.pageIndex = pageIndex;
+            offerRendingTask(task);
+            if (nextCacheTask != null)
+                offerRendingTask(nextCacheTask);
+            if (prevCacheTask != null)
+                offerRendingTask(prevCacheTask);
+        }
+    }
