+        Bitmap b2 = Bitmap.createBitmap(
+                b1,
+                dx1 / 2,
+                dy1 / 2,
+                targetWidth,
+                targetHeight);
+
+        if (b2 != b1) {
+            if (recycle || b1 != source) {
+                b1.recycle();
+            }
+        }
+
+        return b2;
+    }
+    
+    public boolean isUriValid() {
+        if (mUri == null) {
+            return false;
+        }
+        try {
+            ParcelFileDescriptor pfd =
+                    mContentResolver.openFileDescriptor(mUri, "r");
+            if (pfd == null) {
+                Log.e(TAG, "Fail to open URI.");
+                return false;
+            }
+            pfd.close();
+        } catch (IOException ex) {
+            return false;
+        }
