+    public static boolean equals(Object a, Object b) {
+        return (a == b) || (a == null ? false : a.equals(b));
+    }
+
+    public static boolean isPowerOf2(int n) {
+        return (n & -n) == n;
+    }
+
+    public static int nextPowerOf2(int n) {
+        n -= 1;
+        n |= n >>> 16;
+        n |= n >>> 8;
+        n |= n >>> 4;
+        n |= n >>> 2;
+        n |= n >>> 1;
+        return n + 1;
+    }
+
+    public static float distance(float x, float y, float sx, float sy) {
+        float dx = x - sx;
+        float dy = y - sy;
+        return (float) FloatMath.sqrt(dx * dx + dy * dy);
+    }
+
+    public static int clamp(int x, int min, int max) {
+        if (x > max) return max;
+        if (x < min) return min;
+        return x;
+    }
+
+    public static int getDisplayRotation(Activity activity) {
+    	int rotation = 0;
+    	if (Build.VERSION.SDK_INT >= 0x00000008 /*Build.VERSION_CODES.FROYO*/) {
+    		rotation = activity.getWindowManager().getDefaultDisplay().getRotation();
+    	} else {
+    		rotation = activity.getWindowManager().getDefaultDisplay().getOrientation();
+    	}
+        switch (rotation) {
+            case Surface.ROTATION_0: return 0;
+            case Surface.ROTATION_90: return 90;
+            case Surface.ROTATION_180: return 180;
+            case Surface.ROTATION_270: return 270;
+        }
+        return 0;
+    }
+
+    public static void setCameraDisplayOrientation(Activity activity,
+            int cameraId, Camera camera) {
+        // See android.hardware.Camera.setCameraDisplayOrientation for
+        // documentation.
+        Camera.CameraInfo info = new Camera.CameraInfo();
+        Camera.getCameraInfo(cameraId, info);
+        int degrees = getDisplayRotation(activity);
+        int result;
+        if (info.facing == Camera.CameraInfo.CAMERA_FACING_FRONT) {
+            result = (info.orientation + degrees) % 360;
+            result = (360 - result) % 360;  // compensate the mirror
+        } else {  // back-facing
+            result = (info.orientation - degrees + 360) % 360;
+        }
+        camera.setDisplayOrientation(result);
+    }
+    
+	// decode Y, U, and V values on the YUV 420 buffer described as YCbCr_422_SP
+	// by Android
+	public static void decodeYUV(int[] out, byte[] fg, int width, int height)
+			throws NullPointerException, IllegalArgumentException {
+		int sz = width * height;
+		if (out == null)
+			throw new NullPointerException("buffer out is null");
+		if (out.length < sz)
+			throw new IllegalArgumentException("buffer out size " + out.length
+					+ " < minimum " + sz);
+		if (fg == null)
+			throw new NullPointerException("buffer 'fg' is null");
+		if (fg.length < sz)
+			throw new IllegalArgumentException("buffer fg size " + fg.length
+					+ " < minimum " + sz * 3 / 2);
+		int i, j;
+		int Y, Cr = 0, Cb = 0;
+		for (j = 0; j < height; j++) {
+			int pixPtr = j * width;
+			final int jDiv2 = j >> 1;
+			for (i = 0; i < width; i++) {
+				Y = fg[pixPtr];
+				if (Y < 0)
+					Y += 255;
+				if ((i & 0x1) != 1) {
+					final int cOff = sz + jDiv2 * width + (i >> 1) * 2;
+					Cb = fg[cOff];
+					if (Cb < 0)
+						Cb += 127;
+					else
+						Cb -= 128;
+					Cr = fg[cOff + 1];
+					if (Cr < 0)
+						Cr += 127;
+					else
+						Cr -= 128;
+				}
+				int R = Y + Cr + (Cr >> 2) + (Cr >> 3) + (Cr >> 5);
+				if (R < 0)
+					R = 0;
+				else if (R > 255)
+					R = 255;
+				int G = Y - (Cb >> 2) + (Cb >> 4) + (Cb >> 5) - (Cr >> 1)
+						+ (Cr >> 3) + (Cr >> 4) + (Cr >> 5);
+				if (G < 0)
+					G = 0;
+				else if (G > 255)
+					G = 255;
+				int B = Y + Cb + (Cb >> 1) + (Cb >> 2) + (Cb >> 6);
+				if (B < 0)
+					B = 0;
+				else if (B > 255)
+					B = 255;
+				out[pixPtr++] = 0xff000000 + (B << 16) + (G << 8) + R;
+			}
+		}
+	}
+}

