        }

        @Override
        public void handleResult(int resultCode, final Intent data) {
            if (resultCode == Activity.RESULT_OK) {
                new Thread() {
                    @Override
                    public void run() {
                        try {
                            Uri result = Uri.fromFile(getTempImagePath());

                            Log.w(TAG, "result = "  + result);
