	@Override
	protected void onResume() {
		super.onResume();
		mHandler.sendEmptyMessage(2);

		if (mWakeLock == null) {
			//��ȡ������,������Ļ����
			PowerManager pm = (PowerManager) getSystemService(Context.POWER_SERVICE);
			mWakeLock = pm.newWakeLock(PowerManager.SCREEN_BRIGHT_WAKE_LOCK, CLASS_LABEL);
			mWakeLock.acquire();
		}
