	@SuppressWarnings("deprecation")
	public static void prepareEdgeEffect(View view, int placement) {
		final Context context = view.getContext();
		if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.ICE_CREAM_SANDWICH) {
			try {
				if (glowFilter == null) {
					final int color = (placement == PLACEMENT_ALERT ? (isAndroidThemeLight() ? 0xff000000 : 0xffffffff) : (placement == PLACEMENT_MENU ? color_menu_icon : color_glow));
					final Class<?> clazz = ((view instanceof ScrollView) ? ScrollView.class : AbsListView.class);
					Field mEdgeGlow;
					//EdgeEffect edgeEffect;
					mEdgeGlow = clazz.getDeclaredField("mEdgeGlowTop");
					boolean ok = false;
					if (mEdgeGlow != null) {
						ok = true;
						mEdgeGlow.setAccessible(true);
						/*if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
							edgeEffect = (EdgeEffect)mEdgeGlow.get(view);
							if (edgeEffect == null) {
								edgeEffect = new EdgeEffect(context);
								mEdgeGlow.set(view, edgeEffect);
							}
							edgeEffect.setColor(color);
						} else*/ {
							mEdgeGlow.set(view, new BgEdgeEffect(context, color));
						}
					}
					mEdgeGlow = clazz.getDeclaredField("mEdgeGlowBottom");
					if (mEdgeGlow != null) {
						ok = true;
						mEdgeGlow.setAccessible(true);
						/*if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
							edgeEffect = (EdgeEffect)mEdgeGlow.get(view);
							if (edgeEffect == null) {
								edgeEffect = new EdgeEffect(context);
								mEdgeGlow.set(view, edgeEffect);
							}
							edgeEffect.setColor(color);
						} else*/ {
							mEdgeGlow.set(view, new BgEdgeEffect(context, color));
						}
					}
					if (ok || Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP)
						return;
				}
			} catch (Throwable ex) {
				ex.printStackTrace();
			}
		}
		try {
			//if everything else fails, fall back to the old method!
			if (glowFilter == null)
				glowFilter = new PorterDuffColorFilter(color_glow, PorterDuff.Mode.SRC_IN);
			//
			//:D amazing hack/workaround, as explained here:
			//
			//http://evendanan.net/android/branding/2013/12/09/branding-edge-effect/
			Drawable drawable = context.getResources().getDrawable(context.getResources().getIdentifier("overscroll_glow", "drawable", "android"));
			if (drawable != null)
				//the color is treated as SRC, and the bitmap is treated as DST
				drawable.setColorFilter(glowFilter);
			drawable = context.getResources().getDrawable(context.getResources().getIdentifier("overscroll_edge", "drawable", "android"));
			if (drawable != null)
				//hide the edge!!! ;)
				drawable.setColorFilter(glowFilter);//edgeFilter);
		} catch (Throwable ex) {
			ex.printStackTrace();
		}
	}

