		int pix[] = new int[width * height];  
		PixelBuffer.get(pix);//这是将intbuffer中的数据赋值到pix数组中  

		Bitmap bitmap = Bitmap.createBitmap(pix, width, height,Bitmap.Config.ARGB_8888);
		return bitmap;
	}



