						fullrotate_y -= (float)( (curX-event.getX())/10 );
						fullrotate_x -= (float)( (curY-event.getY())/10 );
						curX = event.getX();
						curY = event.getY();
					}
				} 
				break;
			case MotionEvent.ACTION_DOWN:
				touchmode = 1;
				curX = event.getX();
				curY = event.getY();
				break;
			case MotionEvent.ACTION_UP:
				touchmode = 0;
				curX = event.getX();
				curY = event.getY();
			    break;
    	}
		return true;
	}	

