		ByteBuffer nbb = ByteBuffer.allocateDirect(12 * 4 * 6);
		nbb.order(ByteOrder.nativeOrder());
		normBuffer = nbb.asFloatBuffer();
		// Read images. Find the aspect ratio and adjust the vertices
		// accordingly.
		for (int face = 0; face < 6; face++) {
