+        scaleStart = 0f;
+        vTranslate = null;
+        vTranslateStart = null;
+        pendingScale = 0f;
+        sPendingCenter = null;
+        sRequestedCenter = null;
+        isZooming = false;
+        isPanning = false;
+        maxTouchCount = 0;
+        fullImageSampleSize = 0;
+        vCenterStart = null;
+        vDistStart = 0;
+        anim = null;
+        if (newImage) {
+            if (decoder != null) {
+                synchronized (decoderLock) {
+                    decoder.recycle();
+                    decoder = null;
+                }
+            }
+            sWidth = 0;
+            sHeight = 0;
+            sOrientation = 0;
+            readySent = false;
