+    /**
+     * Async task used to get image details without blocking the UI thread.
+     */
+    private static class BitmapInitTask extends AsyncTask<Void, Void, int[]> {
+        private final WeakReference<SubsamplingScaleImageView> viewRef;
+        private final WeakReference<Context> contextRef;
+        private final String source;
+        private BitmapRegionDecoder decoder;
+        public enum SourceType{
+            ASSET,
+            FILE_PATH,
+            URL
+        }
+        private SourceType sourceType;
+
+        public BitmapInitTask(SubsamplingScaleImageView view, Context context, String source, SourceType sourceType) {
+            this.viewRef = new WeakReference<SubsamplingScaleImageView>(view);
+            this.contextRef = new WeakReference<Context>(context);
+            this.source = source;
+            this.sourceType = sourceType;
+        }
+
+        @TargetApi(Build.VERSION_CODES.GINGERBREAD_MR1)
+        @Override
+        protected int[] doInBackground(Void... params) {
+            try {
+                if (viewRef != null && contextRef != null) {
+                    Context context = contextRef.get();
+                    if (context != null) {
+                        int exifOrientation = ORIENTATION_0;
+                        switch (sourceType){
+                            case ASSET:
+                                decoder = BitmapRegionDecoder.newInstance(context.getAssets().open(source, AssetManager.ACCESS_RANDOM), true);
+                                break;
+                            case FILE_PATH:
+                                decoder = BitmapRegionDecoder.newInstance(source, true);
+                                try {
+                                    ExifInterface exifInterface = new ExifInterface(source);
+                                    int orientationAttr = exifInterface.getAttributeInt(ExifInterface.TAG_ORIENTATION, ExifInterface.ORIENTATION_NORMAL);
+                                    if (orientationAttr == ExifInterface.ORIENTATION_NORMAL) {
+                                        exifOrientation = ORIENTATION_0;
+                                    } else if (orientationAttr == ExifInterface.ORIENTATION_ROTATE_90) {
+                                        exifOrientation = ORIENTATION_90;
+                                    } else if (orientationAttr == ExifInterface.ORIENTATION_ROTATE_180) {
+                                        exifOrientation = ORIENTATION_180;
+                                    } else if (orientationAttr == ExifInterface.ORIENTATION_ROTATE_270) {
+                                        exifOrientation = ORIENTATION_270;
+                                    } else {
+                                        Log.w(TAG, "Unsupported EXIF orientation: " + orientationAttr);
+                                    }
+                                } catch (Exception e) {
+                                    Log.w(TAG, "Could not get EXIF orientation of image");
+                                }
+                                break;
+                            case URL:
+                                InputStream is = getUrlResponse(source);
+                                if(is != null){
+                                    decoder = BitmapRegionDecoder.newInstance(is, true);
+                                }else{
+                                    throw  new IllegalArgumentException("the request image url can not attach!");
+                                }
+                                break;
+                        }
+                        return new int[] { decoder.getWidth(), decoder.getHeight(), exifOrientation };
+                    }
+                }
+            } catch (Exception e) {
+                Log.e(TAG, "Failed to initialise bitmap decoder", e);
+            }
+            return null;
+        }
+
+        // request the url, and get the response
+        private InputStream getUrlResponse(String source) {
+            InputStream is = null;
+            DefaultHttpClient  client = new DefaultHttpClient();
+            HttpGet request = new HttpGet(source);
+            try {
+                is = client.execute(request).getEntity().getContent();
+            } catch (IOException e) {
+                e.printStackTrace();
+            }
+            return is;
+        }
+
+        @Override
+        protected void onPostExecute(int[] xyo) {
+            if (viewRef != null && decoder != null) {
+                final SubsamplingScaleImageView subsamplingScaleImageView = viewRef.get();
+                if (subsamplingScaleImageView != null && decoder != null && xyo != null && xyo.length == 3) {
+                    subsamplingScaleImageView.onImageInited(decoder, xyo[0], xyo[1], xyo[2]);
+                }
+
+            }
+        }
+    }
