+     * guaranteed to be on screen.
+     * @param sCenter Target center point
+     * @return {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder} instance. Call {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder#start()} to start the anim.
+     */
+    public AnimationBuilder animateCenter(PointF sCenter) {
+        if (!isImageReady()) {
+            return null;
+        }
+        return new AnimationBuilder(sCenter);
+    }
+
+    /**
+     * Creates a scale animation builder, that when started will animate a zoom in or out. If this would move the image
+     * beyond the panning limits, the image is automatically panned during the animation.
+     * @param scale Target scale.
+     * @return {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder} instance. Call {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder} to start the anim.
+     */
+    public AnimationBuilder animateScale(float scale) {
+        if (!isImageReady()) {
+            return null;
+        }
+        return new AnimationBuilder(scale);
+    }
+
+    /**
+     * Creates a scale animation builder, that when started will animate a zoom in or out. If this would move the image
+     * beyond the panning limits, the image is automatically panned during the animation.
+     * @param scale Target scale.
+     * @return {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder} instance. Call {@link xiaofan.llongimageview.view.SubsamplingScaleImageView.AnimationBuilder#start()} to start the anim.
