+                            zoomTimeline(mProject.getZoomLevel() + ZOOM_STEP, true);
+                        }
+
+                        if (mLastScaleFactorSign < SCALE_TOLERANCE) {
+                            mLastScaleFactorSign++;
+                        }
+                    }
+                }
+
