+                imageBitmap.getPixels(framingBuffer, 0, mScaledWidth, 0,
+                                                        tmp, newWidth, 1);
+                intBuffer = byteBuffer.asIntBuffer();
+                intBuffer.put(framingBuffer, 0, newWidth);
+                dos.write(array);
+                tmp += 1;
+            }
+            fl.close();
+        }
+        imageBitmap.recycle();
+    }
