+            clipSettings.mediaRendering = mMANativeHelper
+                .getMediaItemRenderingMode(getRenderingMode());
+            clipSettings.rgbWidth = getScaledWidth();
+            clipSettings.rgbHeight = getScaledHeight();
+
+        }
