+    /**
+     * スタックトレースの文字列取得
+     @ param throwable Throwableクラスのインスタンス
+     * @return スタックトレースの文字列
+     */
+    public String getStackTrace(Throwable throwable) {
+        String value = null;
+        try {
+            StringWriter sw = null;
+            try {
+                sw = new StringWriter();
+                throwable.printStackTrace(new PrintWriter(sw));
+                value = sw.toString();
+            } finally {
+                if (sw != null) {
+                    sw.close();
+                }
+            }
+        } catch (Exception e) {
+            value = throwable.getMessage();
+        }
+        return value;
+    }
