+
+        //Log.d("SlidePuzzle","onSingleTapUp status="+status);
+        if (status == StatusReady) {
+            makeGame();
+            status = StatusDisplayAnswer;
+            wakeup();
+            rc = true;
+        }
+
+        return rc;
