+    /**
+     * 全画面の描画
+     */
+    public void repaint() {
+        Canvas canvas = null;
+
+        if (!surfaceCreated) {
+            return;
+        }
+
+        try {
+            canvas = holder.lockCanvas();
+            synchronized (holder) {
+                onDraw(canvas);
+            }
+        } catch (Exception e) {
+            Log.e("SlidePuzzle",""+getStackTrace(e));
+        } finally {
+            if (canvas != null) {
+                holder.unlockCanvasAndPost(canvas);
+            }
+        }
+    }
+
+    /**
+     * 画面の一部を描画
+     * @param x 描画する左上のX座標
+     * @param y 描画する左上のY座標
+     * @param w 描画する幅
+     * @param h 描画する高さ
+     */
+    public void repaint(int x,int y,int w,int h) {
+        Canvas canvas = null;
+
+        if (!surfaceCreated) {
+            return;
+        }
+
+        try {
+            canvas = holder.lockCanvas();
+            canvas.save(Canvas.CLIP_SAVE_FLAG);
+            canvas.clipRect(x,y,x+w,y+h);
+
+            synchronized (holder) {
+                onDraw(canvas);
+            }
+
+            canvas.restore();
+        } catch (Exception e) {
+            Log.e("SlidePuzzle",""+getStackTrace(e));
+        } finally {
+            if (canvas != null) {
+                holder.unlockCanvasAndPost(canvas);
+            }
+        }
+    }
