+        Paint paint;
+
+        paint = new Paint();
+        paint.setStyle(Paint.Style.FILL);
+        paint.setARGB(0xff,0xff,0xff,0xff); //背景色
+        canvas.drawRect(0,0,getWidth(),getHeight(),paint);
+        if (logoImg != null) {
+            xx = (getWidth() - logoImg.getWidth()) / 2;
+            yy = (getHeight() - logoImg.getHeight()) / 2;
