+     * 背景の描画
+     * @param canvas 描画時に使われるCanvas
+     */
+    private void paintBg(Canvas canvas) {
+        //背景を塗りつぶす
+        canvas.drawRect(0,0,getWidth(),getHeight(),bgPaint);
