+	private Bitmap getFallback(){
+		
+		Bitmap bm = null;
+		
+		View view = v.get();
+		if(view != null){
+		
+			String key = Integer.toString(fallback);			
+			bm = memGet(key);
+			
+			if(bm == null){
+				bm = BitmapFactory.decodeResource(view.getResources(), fallback);
+				
+				if(bm != null){
+					memPut(key, bm);
+				}
+			}
+		}
+		
+		return bm;
+	}
