+		
+		String key = Integer.toString(resId);			
+		Bitmap bm = memGet(key, 0, 0);
+		
+		if(bm == null){
+			bm = BitmapFactory.decodeResource(context.getResources(), resId);
+			
+			if(bm != null){
+				memPut(key, 0, 0, bm, false);
+			}
+		}
+		
+		return bm;
+	}
