+	 * Sets the pixel criteria for small images. Small images are cached in a separate cache.
+	 *
+	 * Default is 50x50 (2500 pixels)
+	 *
+	 * @param pixels the small image pixel criteria
+	 */
+	public static void setSmallPixel(int pixels){
+		SMALL_PIXELS = pixels;
+		clearCache();
